func (ml *ModelLoader) grpcModel(backend string, o *Options) func(string, string, string) (*Model, error) {
	return func(modelID, modelName, modelFile string) (*Model, error) {
		xlog.Debug("Loading Model with gRPC", "modelID", modelID, "file", modelFile, "backend", backend)

		// Distributed mode: delegate to the model router if set. No load
		// event is emitted here: this branch runs per inference request and
		// the actual load happens on the worker node. The options finalizer
		// does not run here either: the router completes the options itself
		// when it sends a load, so a request for a loaded model costs nothing
		// extra and the options it stores hold no secret.
		ml.mu.Lock()
		router := ml.modelRouter
		ml.mu.Unlock()
		if router != nil {
			xlog.Info("Routing model to remote node via ModelRouter", "modelID", modelID, "backend", backend)
			// This measures the callback, not transport or worker execution.
			end := diagnostics.Begin(o.context, diagnostics.PhaseModelRouterCallback)
			model, err := router(o.context, backend, modelID, modelName, modelFile, o.configRevision, o.gRPCOptions, o.parallelRequests)
			outcome := diagnostics.OutcomeOK
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				outcome = diagnostics.OutcomeCanceled
			} else if err != nil {
				outcome = diagnostics.OutcomeError
			}
			end(outcome, 0)
			return model, err
		}

		o, err := o.finalized()
		if err != nil {
			return nil, err
		}
		uri := ml.GetAllExternalBackends(o)[backend]
		start := time.Now()
		started := BackendLoadEvent{ModelID: modelID, ModelName: modelName, Backend: backend, BackendURI: uri}
		finish, admissionErr := ml.notifyLoadStarted(started)
		if admissionErr != nil {
			return nil, admissionErr
		}
		m, err := ml.spawnGRPCModel(backend, uri, o, modelID, modelName, modelFile)
		completed := BackendLoadEvent{
			ModelID:    modelID,
			ModelName:  modelName,
			Backend:    backend,
			BackendURI: uri,
			Duration:   time.Since(start),
			Err:        err,
		}
		ml.notifyLoadObserver(completed)
		if finish != nil {
			finish(completed)
		}
		return m, err
	}
}

