func resolveProfile(ctx context.Context, files []FileInput, sizeResolver SizeResolver, ggufReader GGUFMetadataReader) modelProfile {
	var p modelProfile
	var firstGGUFURI string

	for i := range files {
		f := &files[i]
		if !IsWeightFile(f.URI) {
