{"type":"assistant","message":{"content":[{"id":"call_00_ktupx6lzv2unf2wrxtfolby2","input":{"file_path":"/home/wll/uidreczz28dV8YMfCbV/pkg/residency/types.go","content":"// Package residency keeps the per-host account of what models hold in memory,
// decides whether a load may start, and explains a refusal in bytes.
//
// The ledger has exactly one writer: the model lifecycle. A successful load
// settles an account, an unload, eviction, crash or lost backend removes it,
// and a calibration updates its measured size. Everything else is a reader.
//
// Two pools are tracked because a host runs models from two kinds of memory:
// device memory (VRAM) and host memory (RAM). A model is charged to exactly one
// pool, the one the backend will allocate in. A pool with no configured limit
// never refuses a load and never triggers a reclaim, so an installation that
// sets nothing behaves as it did before.
package residency

import (
	"fmt"
	"time"

	"github.com/mudler/LocalAI/pkg/vram"
)

// Provenance says how a byte figure was obtained. It is deliberately part of
// the value: a measured zero and an unknown size are different facts, and a
// rejection that cannot say which is not auditable.
type Provenance string

const (
	// Measured means the host read the figure: a file's size, or the resident
	// memory accounted to the backend process.
	Measured Provenance = "measured"
	// Estimated means the figure was derived from metadata (a GGUF header, a
	// gallery size, a HuggingFace file listing) rather than observed.
	Estimated Provenance = "estimated"
	// Unknown means no trustworthy figure exists. Bytes is then not a zero.
	Unknown Provenance = "unknown"
)

// Normalized maps the zero value and any unexpected string to Unknown, so a
// Component built by an older caller can never be mistaken for a measured zero.
func (p Provenance) Normalized() Provenance {
	switch p {
	case Measured, Estimated:
		return p
	default:
		return Unknown
	}
}

// worse combines two provenances, keeping the least trustworthy.
func worse(a, b Provenance) Provenance {
	a, b = a.Normalized(), b.Normalized()
	if a == Unknown || b == Unknown {
		return Unknown
	}
	if a == Estimated || b == Estimated {
		return Estimated
	}
	return Measured
}

// Component is one line of a model's residency account with how it was known.
type Component struct {
	Bytes      uint64     `json:"bytes"`
	Provenance Provenance `json:"provenance"`
}

// Known reports whether the figure is a real number (measured or estimated).
func (c Component) Known() bool {
	return c.Provenance.Normalized() != Unknown
}

// Normalized fills in an unset provenance as Unknown.
func (c Component) Normalized() Component {
	return Component{Bytes: c.Bytes, Provenance: c.Provenance.Normalized()}
}

// Display renders a component for a human. Unknown is never rendered as a
// zero: it says so.
func (c Component) Display() string {
	if !c.Known() {
		return "unknown"
	}
	return fmt.Sprintf("%s (%s)", vram.FormatBytes(c.Bytes), c.Provenance.Normalized())
}

// AddComponent sums components, keeping the least trustworthy provenance.
func AddComponent(a, b Component) Component {
	a, b = a.Normalized(), b.Normalized()
	return Component{Bytes: a.Bytes + b.Bytes, Provenance: worse(a.Provenance, b.Provenance)}
}

// PoolKind names the memory a model is charged to.
type PoolKind string

const (
	// PoolDevice is memory local to a GPU (VRAM).
	PoolDevice PoolKind = "device"
	// PoolHost is system memory (RAM).
	PoolHost PoolKind = "host"
)

// Valid reports whether the pool is one of the two known pools.
func (p PoolKind) Valid() bool { return p == PoolDevice || p == PoolHost }

// Account is one model's residency entry. It exists once per model however many
// names resolve to it.
type Account struct {
	Model   string   `json:"model"`
	Aliases []string `json:"aliases,omitempty"`
	Backend string   `json:"backend,omitempty"`
	Address string   `json:"address,omitempty"`
	Pool    PoolKind `json:"pool"`

	// Weights, Context and Extras are the three parts of the account. Context
	// is the KV/attention cache; Extras covers projectors and companion files.
	Weights Component `json:"weights"`
	Context Component `json:"context"`
	Extras  Component `json:"extras"`

	// Measured is the process-accounted resident size, when the host can read
	// it. It is what the ledger charges, so a successful load settles at the
	// real figure rather than the estimate.
	Measured *Component `json:"measured,omitempty"`

	Pinned   bool      `json:"pinned"`
	Serving  bool      `json:"serving"`
	LoadedAt time.Time `json:"loaded_at"`
	LastUsed time.Time `json:"last_used"`
}

// EstimatedTotal sums the three components. An unknown component makes the
// total unknown, though the known bytes are still reported.
func (a Account) EstimatedTotal() Component {
	total := AddComponent(a.Weights, a.Context)
	return AddComponent(total, a.Extras)
}

// Charge is the figure the ledger counts for this account: the measured
// resident size when one exists, otherwise the estimate.
func (a Account) Charge() Component {
	if a.Measured != nil {
		return a.Measured.Normalized()
	}
	return a.EstimatedTotal()
}

// SameIncarnation reports whether other describes the same loaded backend:
// same model at the same address (or both without an address). It lets a
// re-settle after an alias load update one entry instead of adding a second.
func (a Account) SameIncarnation(other Account) bool {
	return a.Model == other.Model && a.Address == other.Address
}

// PoolSummary is the roll-up of one pool.
type PoolSummary struct {
	Kind PoolKind `json:"kind"`

	// CapacityBytes is the detected physical capacity before any cap.
	CapacityBytes uint64 `json:"capacity_bytes"`
	CapacityKnown bool   `json:"capacity_known"`

	// LimitBytes is the usable cap after applying the configured budget
	// (0 when unconfigured). LimitConfigured distinguishes "no cap" from a
	// cap of zero, which is never a valid limit.
	LimitBytes      uint64 `json:"limit_bytes"`
	LimitConfigured bool   `json:"limit_configured"`

	ResidentBytes uint64 `json:"resident_bytes"`
	ReservedBytes uint64 `json:"reserved_bytes"`

	// HeadroomBytes is what a new load may still take. HeadroomKnown is false
	// when neither a limit nor a capacity is known; it is never reported as a
	// hard zero in that case.
	HeadroomBytes uint64 `json:"headroom_bytes"`
	HeadroomKnown bool   `json:"headroom_known"`

	Accounts int `json:"accounts"`
	// UnknownAccounts names the accounts whose charge is not known, so a
	// reader can tell a genuinely empty pool from an unmeasured one.
	UnknownAccounts []string `json:"unknown_accounts,omitempty"`
}

// Summary is the two-pool roll-up.
type Summary struct {
	Enabled bool        `json:"enabled"`
	Device  PoolSummary `json:"device"`
	Host    PoolSummary `json:"host"`
}

// ReservationView is one in-flight load's hold on a pool.
type ReservationView struct {
	ID         uint64     `json:"id"`
	Model      string     `json:"model"`
	Backend    string     `json:"backend,omitempty"`
	Pool       PoolKind   `json:"pool"`
	Bytes      uint64     `json:"bytes"`
	Provenance Provenance `json:"provenance"`
	Since      time.Time  `json:"since"`
	ExpiresAt  time.Time  `json:"expires_at,omitempty"`
}

// Rejection is a refusal that was actually decided, kept so an operator can
// audit why a load did not start. It deliberately holds only model names,
// provenances and byte figures: no weight path, download URL or remote address
// can leak through it.
type Rejection struct {
	At          time.Time  `json:"at"`
	Model       string     `json:"model"`
	Backend     string     `json:"backend,omitempty"`
	Pool        PoolKind   `json:"pool"`
	NeededBytes uint64     `json:"needed_bytes"`
	Provenance  Provenance `json:"provenance"`
	Resident    uint64     `json:"resident_bytes"`
	Reserved    uint64     `json:"reserved_bytes"`
	Limit       uint64     `json:"limit_bytes"`
	Shortfall   uint64     `json:"shortfall_bytes"`
	// Reclaimable names the models that could have been evicted.
	Reclaimable []string `json:"reclaimable,omitempty"`
	// Held lists the models that could not be evicted because they are pinned,
	// serving a request or loading.
	Held    []string `json:"held,omitempty"`
	Reason  string   `json:"reason"`
}

// CandidateDecision is what admission decided for one candidate backend engine
// under the same model configuration.
type CandidateDecision struct {
	Backend  string `json:"backend"`
	Admitted bool   `json:"admitted"`
	Skipped  bool   `json:"skipped"`
	Reason   string `json:"reason,omitempty"`
}

// AllCandidatesRejectedError is returned when no candidate engine could be
// admitted. It carries the per-candidate reasons so the caller can explain the
// whole trial, not only the last failure.
type AllCandidatesRejectedError struct {
	Model      string              `json:"model"`
	Candidates []CandidateDecision `json:"candidates"`
}

func (e *AllCandidatesRejectedError) Error() string {
	msg := fmt.Sprintf("model %q was not started: no candidate backend engine fits", e.Model)
	if len(e.Candidates) == 0 {
		return msg
	}
	msg += " ("
	for i, c := range e.Candidates {
		if i > 0 {
			msg += "; "
		}
		msg += c.Backend + ": " + c.Reason
	}
	return msg + ")"
}

// View is the observation surface: per-model accounts, the two pool roll-ups,
// in-flight reservations and the most recent refusals.
type View struct {
	Enabled bool `json:"enabled"`
	// Note explains why the ledger is disabled, when it is.
	Note         string            `json:"note,omitempty"`
	Device       PoolSummary       `json:"device"`
	Host         PoolSummary       `json:"host"`
	Accounts     []Account         `json:"accounts"`
	Reservations []ReservationView `json:"reservations,omitempty"`
	Rejections   []Rejection       `json:"recent_rejections,omitempty"`
}
