// ResolveLimit turns a configured budget string into a usable ceiling.
// detected is the physical capacity the cap is resolved against; a percentage
// is a fraction of it and an absolute value is clamped to it.
func ResolveLimit(detected uint64, configured string) Limit {
	limit := Limit{CapacityBytes: detected, CapacityKnown: detected > 0}
	budget, err := vrambudget.Parse(configured)
	if err != nil {
		// A malformed value must not wedge allocation. Log the value itself
		// (it is operator input, not a credential) and fall back to uncapped.
		xlog.Warn("[residency] ignoring an unusable memory budget; treating the pool as uncapped",
			"value", configured, "error", err)
		return limit
	}
	if !budget.IsSet() {
		return limit
	}
	ceiling := budget.Ceiling(detected)
	if ceiling == 0 {
		// Not reachable through Parse for a set budget with a positive
		// capacity, but an unset/unknown capacity can resolve to zero. Keep
		// that "uncapped" rather than "nothing may load".
		return limit
	}
	limit.LimitConfigured = true
	limit.LimitBytes = ceiling
	return limit
}

// ResolveLimits resolves both pools from the configured budget strings.
func ResolveLimits(deviceCapacity, hostCapacity uint64, vramBudget, memoryBudget string) (device, host Limit) {
	return ResolveLimit(deviceCapacity, vramBudget), ResolveLimit(hostCapacity, memoryBudget)
}

// Headroom is the bytes a new load may still take in this pool, and whether
// that figure is known at all.
func (l Limit) Headroom(resident, reserved uint64) (bytes uint64, known bool) {
	ceiling := l.CapacityBytes
	if l.LimitConfigured {
		ceiling = l.LimitBytes
	}
	if ceiling == 0 {
		return 0, false
	}
	used := resident + reserved
	if used >= ceiling {
		return 0, true
	}
	return ceiling - used, true
}

// WouldFit reports whether need fits the pool. An unconfigured cap always
// fits: without an operator limit a load is never refused.
func (l Limit) WouldFit(need, resident, reserved uint64) bool {
	if !l.LimitConfigured {
		return true
	}
	ceiling := l.LimitBytes
	if ceiling == 0 {
		return true
	}
	return resident+reserved+need <= ceiling
}
