import (
	"context"
	"errors"
	"fmt"
	"slices"
	"sync"
	"time"

	"github.com/mudler/xlog"
)

// ReclaimOrder is the order in which reclaimable accounts are chosen.
type ReclaimOrder string

const (
	// ReclaimLeastRecentlyUsed frees the model that has gone unused longest.
	ReclaimLeastRecentlyUsed ReclaimOrder = "lru"
	// ReclaimLargestFirst frees the biggest resident model first, to free the
	// most memory per stop.
	ReclaimLargestFirst ReclaimOrder = "largest"
)

// Config configures a Ledger. The zero value tracks nothing.
type Config struct {
	Device Limit
	Host   Limit

	// ReserveTTL bounds how long an admitted load may hold a reservation
	// without settling it. A load that fails, is cancelled, or hangs returns
	// its bytes at the latest then.
	ReserveTTL time.Duration

	ReclaimOrder  ReclaimOrder
	ReclaimMax    int
	ReclaimBudget time.Duration

	MaxRejections int

	// Now is injectable for tests.
	Now func() time.Time
}

// Defaults for a Ledger that was not given them.
const (
	DefaultReserveTTL    = time.Hour
	DefaultReclaimMax    = 4
	DefaultReclaimBudget = 30 * time.Second
	DefaultMaxRejections = 10
)

// ErrNotAdmitted is returned when a reservation is used after it was released.
var ErrNotAdmitted = errors.New("residency: reservation is no longer held")

// Reservation is one admitted load's hold on a pool. Its bytes are counted in
// the pool's reserved figure until it is committed, released or expires.
type Reservation struct {
	ID         uint64
	Model      string
	Backend    string
	Pool       PoolKind
	Bytes      uint64
	Provenance Provenance
	Since      time.Time
	ExpiresAt  time.Time

	ledger *Ledger
	timer  *time.Timer
	once   sync.Once
}

// Ledger is the single-writer residency account for one host.
type Ledger struct {
	// admitMu serializes admission and reclaim, so two loads cannot each
	// observe the same free bytes and both take them, and a periodic reclaim
	// cannot evict the model an admission is already evicting.
	admitMu sync.Mutex

	mu       sync.Mutex
	cfg      Config
	accounts map[string]Account // keyed by canonical model name
	evicting map[string]bool    // model names with a reclaim in flight
	reserved map[uint64]*Reservation
	nextID   uint64
	rejected []Rejection
	closed   bool
}

// NewLedger builds a ledger. A zero Limit means "uncapped" for that pool and
// is the default behaviour of the installation.
func NewLedger(cfg Config) *Ledger {
	if cfg.Now == nil {
		cfg.Now = time.Now
	}
	if cfg.ReserveTTL <= 0 {
		cfg.ReserveTTL = DefaultReserveTTL
	}
	if cfg.ReclaimMax <= 0 {
		cfg.ReclaimMax = DefaultReclaimMax
	}
	if cfg.ReclaimBudget <= 0 {
		cfg.ReclaimBudget = DefaultReclaimBudget
	}
	if cfg.ReclaimOrder == "" {
		cfg.ReclaimOrder = ReclaimLeastRecentlyUsed
	}
	if cfg.MaxRejections <= 0 {
		cfg.MaxRejections = DefaultMaxRejections
	}
	return &Ledger{
		cfg:      cfg,
		accounts: map[string]Account{},
		evicting: map[string]bool{},
		reserved: map[uint64]*Reservation{},
	}
}

// Configure replaces the limits. It is called when the operator edits a budget.
// A ledger reconfigured to uncapped admits everything again; accounts are kept.
func (l *Ledger) Configure(cfg Config) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if cfg.Now == nil {
		cfg.Now = l.cfg.Now
	}
	if cfg.ReserveTTL <= 0 {
		cfg.ReserveTTL = l.cfg.ReserveTTL
	}
	if cfg.ReclaimMax <= 0 {
		cfg.ReclaimMax = l.cfg.ReclaimMax
	}
	if cfg.ReclaimBudget <= 0 {
		cfg.ReclaimBudget = l.cfg.ReclaimBudget
	}
	if cfg.ReclaimOrder == "" {
		cfg.ReclaimOrder = l.cfg.ReclaimOrder
	}
	if cfg.MaxRejections <= 0 {
		cfg.MaxRejections = l.cfg.MaxRejections
	}
	l.cfg = cfg
}

// Limits returns the current resolved limits.
func (l *Ledger) Limits() (device, host Limit) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.cfg.Device, l.cfg.Host
}

// LimitFor returns the configured limit for one pool.
func (l *Ledger) LimitFor(pool PoolKind) Limit {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.limitLocked(pool)
}

func (l *Ledger) limitLocked(pool PoolKind) Limit {
	if pool == PoolHost {
		return l.cfg.Host
	}
	return l.cfg.Device
}

// Close stops reservation timers. It is safe to call more than once.
func (l *Ledger) Close() {
	l.mu.Lock()
	l.closed = true
	reservations := make([]*Reservation, 0, len(l.reserved))
	for _, r := range l.reserved {
		reservations = append(reservations, r)
	}
	l.reserved = map[uint64]*Reservation{}
	l.mu.Unlock()
	for _, r := range reservations {
		if r.timer != nil {
			r.timer.Stop()
		}
	}
}

// ---------------------------------------------------------------------------
// Writer: load settled, calibrated, removed.

// Settle records (or updates) a resident account. It is the one write path for
// a successful load; unload, eviction and calibration funnel through it or
// Remove, so an alias or a repeated load never double-counts.
func (l *Ledger) Settle(a Account) {
	if a.Model == "" {
		return
	}
	a.Pool = normalizePool(a.Pool, a.Address)
	a.Weights = a.Weights.Normalized()
	a.Context = a.Context.Normalized()
	a.Extras = a.Extras.Normalized()
	if a.Measured != nil {
		m := a.Measured.Normalized()
		a.Measured = &m
	}
	now := l.now()

	l.mu.Lock()
	defer l.mu.Unlock()
	existing, ok := l.accounts[a.Model]
	if ok {
		// A different incarnation at the same name replaces the entry; the
		// same incarnation merges aliases and takes the newer figures.
		if existing.Address != a.Address && existing.Address != "" && a.Address != "" {
			a.Aliases = appendUnique(a.Aliases, existing.Aliases...)
			a.Aliases = appendUnique(a.Aliases, existing.Model)
		} else {
			a.Aliases = appendUnique(existing.Aliases, a.Aliases...)
		}
		if a.LoadedAt.IsZero() {
			a.LoadedAt = existing.LoadedAt
		}
	} else if a.LoadedAt.IsZero() {
		a.LoadedAt = now
	}
	if a.LastUsed.IsZero() {
		a.LastUsed = a.LoadedAt
	}
	l.accounts[a.Model] = a
}

// Alias records that alias resolves to the resident model target. It is used
// when a load arrives under a different name than the one already accounted.
func (l *Ledger) Alias(target, alias string) {
	if target == alias || alias == "" {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	a, ok := l.accounts[target]
	if !ok {
		return
	}
	a.Aliases = appendUnique(a.Aliases, alias)
	l.accounts[target] = a
}

// Calibrate replaces the measured figure of a resident model. A model that is
// not resident is ignored: calibration never creates an account (that is the
// load's job) and a failed calibration cannot disturb what is loaded.
func (l *Ledger) Calibrate(model string, measured Component) bool {
	if !measured.Known() {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	a, ok := l.accounts[model]
	if !ok {
		return false
	}
	m := measured.Normalized()
	a.Measured = &m
	l.accounts[model] = a
	return true
}

// Touch updates the last-used time of a resident model, which is what the LRU
// reclaim order reads.
func (l *Ledger) Touch(model string, at time.Time) {
	l.mu.Lock()
	defer l.mu.Unlock()
	a, ok := l.accounts[model]
	if !ok {
		return
	}
	if at.IsZero() {
		at = l.now()
	}
	a.LastUsed = at
	l.accounts[model] = a
}

// SetFlags updates the pinned/serving flags a reclaim reads. It lets the
// lifecycle keep them current without rewriting the whole account.
func (l *Ledger) SetFlags(model string, pinned, serving bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	a, ok := l.accounts[model]
	if !ok {
		return
	}
	a.Pinned, a.Serving = pinned, serving
	l.accounts[model] = a
}

// Remove drops a model's account. It is called for a graceful unload, an
// eviction, a crashed process and a lost backend alike, so every exit path
// releases the same way.
func (l *Ledger) Remove(model string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	delete(l.accounts, model)
	delete(l.evicting, model)
}

// RemoveByAddress drops the account holding the given backend address.
func (l *Ledger) RemoveByAddress(address string) {
	if address == "" {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	for name, a := range l.accounts {
		if a.Address == address {
			delete(l.accounts, name)
		}
	}
}

// Resident reports whether the ledger holds an account for model.
func (l *Ledger) Resident(model string) (Account, bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	a, ok := l.accounts[model]
	return a, ok
}

// ---------------------------------------------------------------------------
// Writer: admission and reclaim.

// Evictor stops a resident model to free its bytes. The ledger has already
// marked the account, so a concurrent reclaim skips it; the evictor must not
// block indefinitely (the ledger also enforces a time budget around the call).
type Evictor func(a Account) error

// Need is one load's request to the ledger.
type Need struct {
	// Account carries the identity and the estimate. Model is required; Pool
	// selects the memory, Address and Backend are informational.
	Account Account
}

// Decision is the outcome of one admission.
type Decision struct {
	Admitted    bool
	Reservation *Reservation
	Rejection   *Rejection
	Evicted     []string
	// Uncertain is set when the decision had to cross an unknown size. The
	// load is admitted (a missing estimate must not refuse a load that could
	// succeed), and the pool's headroom is reported unknown.
	Uncertain bool
	Note      string
}

// Admit decides whether a load may start, reclaiming residents if the pool is
// over its limit, and reserves the bytes on success.
//
// A load refused here never starts a process: the caller must check the result
// before spawning the backend.
func (l *Ledger) Admit(ctx context.Context, need Need, evict Evictor) Decision {
	l.admitMu.Lock()
	defer l.admitMu.Unlock()

	a := need.Account
	a.Pool = normalizePool(a.Pool, a.Address)
	if a.Model == "" {
		return Decision{Admitted: true} // nothing to account; never block
	}

	var decision Decision
	for attempt := 0; ; attempt++ {
		l.mu.Lock()
		l.reapExpiredLocked(l.now())
		limit := l.limitLocked(a.Pool)
		usage := l.usageLocked(a.Pool)
		l.mu.Unlock()

		charge := a.Charge()
		needBytes, needKnown := charge.Bytes, charge.Known()

		if !limit.LimitConfigured {
			// Uncapped: admit and still reserve, so in-flight loads are
			// visible and the accounting stays honest about what is loading.
			decision.Admitted = true
			decision.Uncertain = !needKnown
			if !needKnown {
				decision.Note = "the model's size cannot be determined; admitted uncapped"
			}
			decision.Reservation = l.reserve(a, needBytes, charge.Provenance)
			return decision
		}

		// A known usage that already fits needs no reclaim.
		if usage.knownComplete && usage.resident+usage.reserved+needBytes <= limit.LimitBytes {
			decision.Admitted = true
			decision.Reservation = l.reserve(a, needBytes, charge.Provenance)
			return decision
		}

		// Try to reclaim until the need fits or the budget runs out.
		evicted, more := l.reclaimLocked(ctx, a.Pool, a.Model, evict, limit, a, usage)
		decision.Evicted = append(decision.Evicted, evicted...)
		if len(evicted) > 0 && attempt < 4 {
			continue // recompute with the freed accounts
		}
		if more {
			// More reclaim was wanted but the budget ran out (time or count).
			l.mu.Lock()
			usage = l.usageLocked(a.Pool)
			l.mu.Unlock()
			if usage.knownComplete && usage.resident+usage.reserved+needBytes <= limit.LimitBytes {
				decision.Admitted = true
				decision.Reservation = l.reserve(a, needBytes, charge.Provenance)
				return decision
			}
			decision.Rejection = l.rejectLocked(Rejection{
				Model:       a.Model,
				Backend:     a.Backend,
				Pool:        a.Pool,
				NeededBytes: needBytes,
				Provenance:  charge.Provenance.Normalized(),
				Resident:    usage.resident,
				Reserved:    usage.reserved,
				Limit:       limit.LimitBytes,
				Reason:      ReasonReclaimBudget,
			})
			return decision
		}

		l.mu.Lock()
		usage = l.usageLocked(a.Pool)
		l.mu.Unlock()

		// No reclaimable account left. If the usage is not fully known we
		// cannot prove the load does not fit, and refusing would turn an
		// unknown into a guaranteed failure.
		if !usage.knownComplete || !needKnown {
			decision.Admitted = true
			decision.Uncertain = true
			decision.Note = "admitted over the limit because a resident or requested size is unknown"
			decision.Reservation = l.reserve(a, needBytes, charge.Provenance)
			xlog.Warn("[residency] admitting a load whose memory account is incomplete",
				"model", a.Model, "pool", a.Pool, "resident_known", usage.resident,
				"reserved", usage.reserved, "limit", limit.LimitBytes)
			return decision
		}

		decision.Rejection = l.rejectLocked(Rejection{
			Model:       a.Model,
			Backend:     a.Backend,
			Pool:        a.Pool,
			NeededBytes: needBytes,
			Provenance:  charge.Provenance.Normalized(),
			Resident:    usage.resident,
			Reserved:    usage.reserved,
			Limit:       limit.LimitBytes,
			Reclaimable: usage.reclaimable,
			Held:        usage.held,
			Reason:      ReasonNoReclaimable,
		})
		return decision
	}
}

// Reason keys carried in a Rejection. They are stable values a client can
// switch on; the human-readable detail is in the byte fields.
const (
	ReasonLimitExceeded  = "limit_exceeded"
	ReasonNoReclaimable  = "no_reclaimable_accounts"
	ReasonReclaimBudget  = "reclaim_budget_exhausted"
	ReasonReservationTTL = "reservation_timeout"
)

// rejectLocked builds and stores a rejection with its byte shortfall.
func (l *Ledger) rejectLocked(r Rejection) *Rejection {
	if r.At.IsZero() {
		r.At = l.now()
	}
	used := r.Resident + r.Reserved
	if used+r.NeededBytes > r.Limit && r.Limit > 0 {
		r.Shortfall = used + r.NeededBytes - r.Limit
	}
	if r.Reason == "" {
		r.Reason = ReasonLimitExceeded
	}
	l.mu.Lock()
	l.rejected = append(l.rejected, r)
	if over := len(l.rejected) - l.cfg.MaxRejections; over > 0 {
		l.rejected = append([]Rejection(nil), l.rejected[over:]...)
	}
	l.mu.Unlock()
	c := r
	return &c
}

// poolUsage is the internal roll-up an admission needs.
type poolUsage struct {
	resident      uint64
	reserved      uint64
	knownComplete bool
	reclaimable   []string
	held          []string
}

func (l *Ledger) usageLocked(pool PoolKind) poolUsage {
	var u poolUsage
	u.knownComplete = true
	for name, a := range l.accounts {
		if a.Pool != pool {
			continue
		}
		c := a.Charge()
		if !c.Known() {
			u.knownComplete = false
			continue
		}
		u.resident += c.Bytes
		if a.Pinned || a.Serving || l.evicting[name] {
			u.held = append(u.held, name)
		} else {
			u.reclaimable = append(u.reclaimable, name)
		}
	}
	for _, r := range l.reserved {
		if r.Pool == pool {
			u.reserved += r.Bytes
		}
	}
	slices.Sort(u.reclaimable)
	slices.Sort(u.held)
	return u
}

// reclaimLocked evicts residents of pool until the incoming need fits, the
// candidate set is exhausted, or the count/time budget is spent. It holds
// admitMu (through its caller), so at most one admission or periodic reclaim
// evicts at a time, and marks each candidate before its stop begins.
func (l *Ledger) reclaimLocked(ctx context.Context, pool PoolKind, incoming string, evict Evictor, limit Limit, need Account, usage poolUsage) (evicted []string, needMore bool) {
	if evict == nil {
		return nil, false
	}
	candidates := l.orderedCandidatesLocked(pool, incoming)
	if len(candidates) == 0 {
		return nil, false
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if dl, ok := ctx.Deadline(); !ok || time.Until(dl) > l.cfg.ReclaimBudget {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, l.cfg.ReclaimBudget)
		defer cancel()
	}
	charge := need.Charge()
	budget := l.cfg.ReclaimMax
	for _, cand := range candidates {
		if budget <= 0 {
			return evicted, true
		}
		if err := ctx.Err(); err != nil {
			return evicted, true
		}
		select {
		case <-ctx.Done():
			return evicted, true
		default:
		}
		if !l.markEvicting(cand.Model) {
			continue
		}
		budget--
		err := evict(cand)
		if err != nil {
			l.unmarkEvicting(cand.Model)
			xlog.Warn("[residency] could not evict a resident model", "model", cand.Model, "error", err)
			continue
		}
		l.Remove(cand.Model)
		evicted = append(evicted, cand.Model)
		xlog.Info("[residency] evicted a resident model to make room",
			"model", cand.Model, "pool", pool, "incoming", incoming,
			"freed_provenance", cand.Charge().Provenance.Normalized())
		l.mu.Lock()
		usage = l.usageLocked(pool)
		l.mu.Unlock()
		if usage.knownComplete && usage.resident+usage.reserved+charge.Bytes <= limit.LimitBytes {
			return evicted, false
		}
	}
	l.mu.Lock()
	usage = l.usageLocked(pool)
	l.mu.Unlock()
	more := !(usage.knownComplete && usage.resident+usage.reserved+charge.Bytes <= limit.LimitBytes)
	return evicted, more && len(candidates) > 0
}

// orderedCandidatesLocked returns the reclaimable accounts in eviction order.
func (l *Ledger) orderedCandidatesLocked(pool PoolKind, incoming string) []Account {
	var out []Account
	for name, a := range l.accounts {
		if a.Pool != pool || name == incoming || a.Pinned || a.Serving || l.evicting[name] {
			continue
		}
		if !a.Charge().Known() {
			// Its size is unknown, so freeing it cannot be shown to help.
			continue
		}
		out = append(out, a)
	}
	order := l.cfg.ReclaimOrder
	slices.SortFunc(out, func(a, b Account) int {
		if order == ReclaimLargestFirst {
			ab, bb := a.Charge().Bytes, b.Charge().Bytes
			if ab != bb {
				return int(bb) - int(ab)
			}
		}
		switch {
		case a.LastUsed.Before(b.LastUsed):
			return -1
		case a.LastUsed.After(b.LastUsed):
			return 1
		default:
			return 0
		}
	})
	return out
}

func (l *Ledger) markEvicting(model string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.evicting[model] {
		return false
	}
	if _, ok := l.accounts[model]; !ok {
		return false
	}
	l.evicting[model] = true
	return true
}

func (l *Ledger) unmarkEvicting(model string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	delete(l.evicting, model)
}

// Reclaim frees residents of a pool outside an admission, for a periodic
// pressure check. It shares the admission mutex and the eviction marking with
// Admit, so the two can never evict the same model and never run at once.
// It returns the models stopped.
func (l *Ledger) Reclaim(ctx context.Context, pool PoolKind, evict Evictor, wantBytes uint64) []string {
	l.admitMu.Lock()
	defer l.admitMu.Unlock()

	l.mu.Lock()
	limit := l.limitLocked(pool)
	l.mu.Unlock()
	if !limit.LimitConfigured || evict == nil {
		return nil
	}
	candidates := l.orderedCandidatesLocked(pool, "")
	if len(candidates) == 0 {
		return nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	ctx, cancel := context.WithTimeout(ctx, l.cfg.ReclaimBudget)
	defer cancel()

	var evicted []string
	budget := l.cfg.ReclaimMax
	var freed uint64
	for _, cand := range candidates {
		if budget <= 0 || (wantBytes > 0 && freed >= wantBytes) || ctx.Err() != nil {
			break
		}
		if !l.markEvicting(cand.Model) {
			continue
		}
		budget--
		if err := evict(cand); err != nil {
			l.unmarkEvicting(cand.Model)
			xlog.Warn("[residency] periodic reclaim could not evict a resident model", "model", cand.Model, "error", err)
			continue
		}
		l.Remove(cand.Model)
		freed += cand.Charge().Bytes
		evicted = append(evicted, cand.Model)
		xlog.Info("[residency] periodic reclaim evicted a resident model", "model", cand.Model, "pool", pool)
	}
	return evicted
}

// ---------------------------------------------------------------------------
// Reservations.

func (l *Ledger) reserve(a Account, bytes uint64, prov Provenance) *Reservation {
	now := l.now()
	r := &Reservation{
		Model:      a.Model,
		Backend:    a.Backend,
		Pool:       a.Pool,
		Bytes:      bytes,
		Provenance: prov.Normalized(),
		Since:      now,
		ExpiresAt:  now.Add(l.cfg.ReserveTTL),
		ledger:     l,
	}
	l.mu.Lock()
	l.nextID++
	r.ID = l.nextID
	l.reserved[r.ID] = r
	ttl := l.cfg.ReserveTTL
	l.mu.Unlock()

	r.timer = time.AfterFunc(ttl, func() { l.expire(r.ID) })
	return r
}

// expire returns a reservation whose load never settled.
func (l *Ledger) expire(id uint64) {
	l.mu.Lock()
	r, ok := l.reserved[id]
	if !ok {
		l.mu.Unlock()
		return
	}
	delete(l.reserved, id)
	l.mu.Unlock()
	xlog.Warn("[residency] a load reservation timed out and was returned",
		"model", r.Model, "pool", r.Pool, "bytes", r.Bytes)
	l.rejectLocked(Rejection{
		Model:       r.Model,
		Backend:     r.Backend,
		Pool:        r.Pool,
		NeededBytes: r.Bytes,
		Provenance:  r.Provenance,
		Reason:      ReasonReservationTTL,
	})
}

// Bytes and ID identify the hold.
func (r *Reservation) Bytes() uint64 { return r.Bytes }

// Commit settles the reservation into an account. It is the successful load
// path: the reserved hold and the new account are applied together.
func (r *Reservation) Commit(a Account) {
	if r == nil || r.ledger == nil {
		return
	}
	settled := false
	r.once.Do(func() {
		settled = true
		r.ledger.releaseReservation(r)
		r.ledger.Settle(a)
	})
	if !settled {
		// Already committed or released; keep the account current anyway.
		r.ledger.Settle(a)
	}
}

// Release returns the hold without settling an account. A failed, cancelled or
// killed load calls it so the next attempt sees the real headroom.
func (r *Reservation) Release() {
	if r == nil || r.ledger == nil {
		return
	}
	r.once.Do(func() { r.ledger.releaseReservation(r) })
}

func (l *Ledger) releaseReservation(r *Reservation) {
	if r.timer != nil {
		r.timer.Stop()
	}
	l.mu.Lock()
	delete(l.reserved, r.ID)
	l.mu.Unlock()
}

// ReapExpired returns expired reservations early. Timers already do this in
// the background; this makes cleanup deterministic for a caller that wants to
// observe the ledger drain.
func (l *Ledger) ReapExpired() int {
	l.mu.Lock()
	now := l.now()
	expired := make([]uint64, 0)
	for id, r := range l.reserved {
		if !r.ExpiresAt.IsZero() && now.After(r.ExpiresAt) {
			expired = append(expired, id)
			delete(l.reserved, id)
		}
	}
	l.mu.Unlock()
	for _, id := range expired {
		l.rejectLocked(Rejection{Reason: ReasonReservationTTL})
	}
	return len(expired)
}

// reapExpiredLocked drops reservations past their TTL. Callers hold l.mu.
func (l *Ledger) reapExpiredLocked(now time.Time) {
	for id, r := range l.reserved {
		if !r.ExpiresAt.IsZero() && now.After(r.ExpiresAt) {
			delete(l.reserved, id)
		}
	}
}

// ---------------------------------------------------------------------------
// Reader.

// Snapshot is the observation surface. It never writes an account.
func (l *Ledger) Snapshot() View {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.reapExpiredLocked(l.now())

	view := View{Enabled: true}
	view.Device = l.summaryLocked(PoolDevice)
	view.Host = l.summaryLocked(PoolHost)

	view.Accounts = make([]Account, 0, len(l.accounts))
	for _, a := range l.accounts {
		view.Accounts = append(view.Accounts, a)
	}
	slices.SortFunc(view.Accounts, func(a, b Account) int {
		switch {
		case a.Model < b.Model:
			return -1
		case a.Model > b.Model:
			return 1
		default:
			return 0
		}
	})

	view.Reservations = make([]ReservationView, 0, len(l.reserved))
	for _, r := range l.reserved {
		view.Reservations = append(view.Reservations, ReservationView{
			ID: r.ID, Model: r.Model, Backend: r.Backend, Pool: r.Pool,
			Bytes: r.Bytes, Provenance: r.Provenance, Since: r.Since, ExpiresAt: r.ExpiresAt,
		})
	}
	slices.SortFunc(view.Reservations, func(a, b ReservationView) int {
		return int(a.ID) - int(b.ID)
	})

	if n := len(l.rejected); n > 0 {
		view.Rejections = slices.Clone(l.rejected)
	}
	return view
}

func (l *Ledger) summaryLocked(pool PoolKind) PoolSummary {
	limit := l.limitLocked(pool)
	sum := PoolSummary{
		Kind:            pool,
		CapacityBytes:   limit.CapacityBytes,
		CapacityKnown:   limit.CapacityKnown,
		LimitBytes:      limit.LimitBytes,
		LimitConfigured: limit.LimitConfigured,
	}
	knownComplete := true
	for name, a := range l.accounts {
		if a.Pool != pool {
			continue
		}
		sum.Accounts++
		c := a.Charge()
		if !c.Known() {
			knownComplete = false
			sum.UnknownAccounts = append(sum.UnknownAccounts, name)
			continue
		}
		sum.ResidentBytes += c.Bytes
	}
	slices.Sort(sum.UnknownAccounts)
	for _, r := range l.reserved {
		if r.Pool == pool {
			sum.ReservedBytes += r.Bytes
		}
	}
	if limit.LimitConfigured || limit.CapacityKnown {
		sum.HeadroomBytes, sum.HeadroomKnown = limit.Headroom(sum.ResidentBytes, sum.ReservedBytes)
		if !knownComplete {
			// Some resident bytes were not counted, so the headroom is a
			// lower bound at best. Say so instead of rendering it as fact.
			sum.HeadroomKnown = false
		}
	}
	return sum
}

// ---------------------------------------------------------------------------
// Helpers.

func (l *Ledger) now() time.Time {
	if l.cfg.Now != nil {
		return l.cfg.Now()
	}
	return time.Now()
}

// normalizePool defaults an unset pool to device memory. A model with no
// backend address still runs in this process and still allocates somewhere;
// device is the conservative default because it is the pool that runs out.
func normalizePool(p PoolKind, _ string) PoolKind {
	if p.Valid() {
		return p
	}
	return PoolDevice
}

func appendUnique(dst []string, add ...string) []string {
	for _, s := range add {
		if s == "" || slices.Contains(dst, s) {
			continue
		}
		dst = append(dst, s)
	}
	return dst
}

// RejectionMessage renders a refusal for a human: the model, the provenance of
// the figure and the byte difference — never a path, a URL or an address.
func (r Rejection) Message() string {
	need := fmt.Sprintf("%d bytes (%s)", r.NeededBytes, r.Provenance.Normalized())
	pool := string(r.Pool)
	switch r.Reason {
	case ReasonNoReclaimable:
		msg := fmt.Sprintf("model %q needs %s on %s memory but %d bytes are resident and %d reserved against a %d-byte limit: no loaded model can be evicted",
			r.Model, need, pool, r.Resident, r.Reserved, r.Limit)
		if len(r.Held) > 0 {
			msg += fmt.Sprintf(" (pinned, serving or loading: %v)", r.Held)
		}
		return msg
	case ReasonReclaimBudget:
		return fmt.Sprintf("model %q needs %s on %s memory but reclaiming residents ran out of its budget with %d bytes resident and %d reserved against a %d-byte limit",
			r.Model, need, pool, r.Resident, r.Reserved, r.Limit)
	case ReasonReservationTTL:
		return fmt.Sprintf("model %q held a %s-memory reservation for %s bytes that was never settled and has been returned",
			r.Model, pool, need)
	default:
		return fmt.Sprintf("model %q needs %s on %s memory but %d bytes are resident and %d reserved against a %d-byte limit (short by %d bytes)",
			r.Model, need, pool, r.Resident, r.Reserved, r.Limit, r.Shortfall)
	}
}

// Error makes a Decision usable as an error when it refused the load.
func (d Decision) Error() error {
	if d.Admitted || d.Rejection == nil {
		return nil
	}
	return &RejectedError{Rejection: *d.Rejection}
}

// RejectedError wraps a refusal so errors.As can find it.
type RejectedError struct {
	Rejection Rejection
}

func (e *RejectedError) Error() string { return e.Rejection.Message() }

// Unwrap exposes the rejection to errors.As(&RejectedError{}).
func (e *RejectedError) Unwrap() error { return nil }
