				decision.Reservation = l.reserve(a, needBytes, charge.Provenance)
				return decision
			}
			decision.Rejection = l.rejectLocked(Rejection{
				Model:       a.Model,
				Backend:     a.Backend,
				Pool:        a.Pool,
				NeededBytes: needBytes,
				Provenance:  charge.Provenance.Normalized(),
				Resident:    usage.resident,
				Reserved:    usage.reserved,
				Limit:       limit.LimitBytes,
				Reason:      ReasonReclaimBudget,
			})
