	// The estimator's figure is weights plus the KV/compute term. Split it so
	// the ledger can label the cache part honestly: the KV term is the total
	// minus the weights it was computed from.
	total := multi.VRAMForContext(ctxLen)
	if total == 0 {
		total = multi.SizeBytes
	}
	weights := multi.SizeBytes
	var contextBytes uint64
	if total > weights {
		contextBytes = total - weights
	}
	prov := residency.Estimated
	estimate.Weights = residency.Component{Bytes: weights, Provenance: prov}
	estimate.Context = residency.Component{Bytes: contextBytes, Provenance: prov}
	estimate.Extras = residency.Component{Bytes: 0, Provenance: residency.Estimated}
	estimate.WeightBytes = int64(weights)
	if !multi.Approximate {
		// The GGUF header gave the architecture, so the figure is derived from
		// real metadata. It is still an estimate (no load has run yet), which
		// is what Estimated already says.
		estimate.Context = residency.Component{Bytes: contextBytes, Provenance: residency.Estimated}
	}
	return estimate
}

// EstimateForAdmission is the BackendEstimateFunc the loader hands the
// residency ledger. The backend argument is accepted for a future
// per-engine estimate; the figure is currently the same for every engine in
// one model configuration, which is enough to decide admission.
func (ml *ModelLoader) EstimateForAdmission(ctx context.Context, backend string, modelFile string, opts *Options) LoadEstimate {
	return ml.estimateForBackend(ctx, modelFile, opts)
}

const estimateTimeout = 10 * time.Second

// resolveEstimateURI turns a relative model path into a file:// URI so the
// size resolver can stat it, leaving a URI with a scheme untouched.
func resolveEstimateURI(uri, modelsPath string) string {
	if strings.Contains(uri, "://") {
		return uri
	}
	abs := uri
	if !filepath.IsAbs(uri) {
		abs = filepath.Join(modelsPath, uri)
	}
	return "file://" + abs
}

// estimateMeasured returns the process-accounted resident size, when the host
// can read it. It is what settles a successful load at the real figure rather
// than the estimate.
func estimateMeasured(pid int) (residency.Component, bool) {
	if pid <= 0 {
		return residency.Component{}, false
	}
	bytes, ok := processResidentBytes(pid)
	if !ok {
		return residency.Component{}, false
	}
	return residency.Component{Bytes: bytes, Provenance: residency.Measured}, true
}

// processResidentBytes reads the resident bytes of a backend. The Linux
// implementation prefers the GPU-accounted figure (which includes VRAM, where
// the weights really are) and falls back to RSS.
var processResidentBytes = defaultProcessResidentBytes

func defaultProcessResidentBytes(pid int) (uint64, bool) {
	if bytes, ok := readProcessRSS(pid); ok {
		return bytes, true
	}
	return 0, false
}

// readProcessRSS reads the process's resident set size from /proc. It is the
// portable fallback: on a host without DRM accounting it is the only figure
// available, and it still reflects the host-memory half of the load.
func readProcessRSS(pid int) (uint64, bool) {
	if pid <= 0 {
		return 0, false
	}
	data, err := os.ReadFile(filepath.Join("/proc", itoa(pid), "statm"))
	if err != nil {
		return 0, false
	}
	fields := strings.Fields(string(data))
	if len(fields) < 2 {
		return 0, false
	}
	var residentPages uint64
	for _, r := range fields[1] {
		if r < '0' || r > '9' {
			return 0, false
		}
		residentPages = residentPages*10 + uint64(r-'0')
	}
	return residentPages * uint64(os.Getpagesize()), true
}

// itoa is a tiny helper so this file does not pull strconv for one call.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

// downloader import keeps the URI handling aligned with the rest of the VRAM
// estimation; it is referenced here so an unresolvable URI is reported rather
// than silently skipped.
var _ = downloader.URI
