// job is one proto file: where to look for imports, and the Go options.
type job struct {
	protoPath   string
	importPaths []string
	// modulePrefix strips this prefix from a generated file name, matching
	// protoc's --go_opt=module behaviour used by the motion proto.
	modulePrefix string
	grpc         bool
}

func main() {
	outDir := flag.String("out", "pkg/grpc/proto", "output directory")
	flag.Parse()
	jobs := []job{
		{protoPath: "backend/backend.proto", importPaths: []string{"backend"}, grpc: true},
		{protoPath: "pkg/motion/proto/motion.proto", importPaths: []string{"pkg/motion/proto"}},
	}
	if err := run(jobs, *outDir); err != nil {
		fmt.Fprintln(os.Stderr, "protogen:", err)
		os.Exit(1)
	}
}

func run(jobs []job, outDir string) error {
	for _, j := range jobs {
		if err := generate(j, outDir); err != nil {
			return fmt.Errorf("%s: %w", j.protoPath, err)
		}
	}
	return nil
}

func generate(j job, outDir string) error {
	compiler := protocompile.Compiler{
		Resolver:       protocompile.WithStandardImports(&protocompile.SourceResolver{ImportPaths: j.importPaths}),
		SourceInfoMode: protocompile.SourceInfoStandard,
	}
	files, err := compiler.Compile(context.Background(), j.protoPath)
	if err != nil {
		return err
	}
	var targets []*descriptorpb.FileDescriptorProto
	for _, f := range files {
		targets = append(targets, protoutil.ProtoFromFileDescriptor(f))
	}

	plugin, err := protogen.Options{}.New(newRequest(targets))
	if err != nil {
		return err
	}
	for _, f := range plugin.Files {
		if !f.Generate {
			continue
		}
		gengo.GenerateFile(plugin, f)
	}
	resp := plugin.Response()
	if resp.Error != nil {
		return fmt.Errorf("%s", resp.GetError())
	}
	for _, f := range resp.File {
		path := f.GetName()
		if j.modulePrefix != "" {
			path = filepath.Join(outDir, path)
		} else {
			path = filepath.Join(outDir, filepath.Base(path))
		}
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, []byte(f.GetContent()), 0o644); err != nil {
			return err
		}
		fmt.Fprintln(os.Stderr, "wrote", path)
	}
	return nil
}

// newRequest builds the CodeGeneratorRequest the plugin consumes. The Go
