package model

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/mudler/LocalAI/pkg/residency"
	"github.com/mudler/LocalAI/pkg/vram"
)

// LoadEstimate is what the ledger is told about a load before it starts. It is
// built from weight files and, when available, a GGUF header, so the account
// has the three parts the ledger records separately.
type LoadEstimate struct {
	Weights residency.Component
	Context residency.Component
	Extras  residency.Component

	// WeightBytes is the total weight size, also registered for size-aware
	// eviction. It is zero when no estimate could be made.
	WeightBytes int64
}

// Charge is the estimate as one component. An unknown weight size makes the
// whole charge unknown: without weights the rest is not a useful figure.
func (e LoadEstimate) Charge() residency.Component {
	return residency.Account{Weights: e.Weights, Context: e.Context, Extras: e.Extras}.EstimatedTotal()
}

// BackendEstimateFunc builds the estimate for one backend. The backend is the
// engine that will actually run the model; different engines allocate
// differently, so the candidate list is offered each one.
type BackendEstimateFunc func(ctx context.Context, backend string) (LoadEstimate, error)

// estimateForBackend computes a load estimate for a model under one backend.
// It mirrors the file collection the size estimator already does, then charges
// the KV cache term through the GVVRAM estimator at the load's context size.
//
// Everything here is best effort. A remote file that cannot be reached, a
// non-weight file, or missing metadata all degrade to an unknown component,
// never to a refusal.
func (ml *ModelLoader) estimateForBackend(ctx context.Context, modelFile string, opts *Options) LoadEstimate {
	if opts == nil {
		return LoadEstimate{
			Weights: residency.Component{Provenance: residency.Unknown},
			Context: residency.Component{Provenance: residency.Unknown},
			Extras:  residency.Component{Provenance: residency.Unknown},
		}
	}
	var files []vram.FileInput
	seen := map[string]bool{}

	add := func(uri string, knownSize int64) {
		if uri == "" || !vram.IsWeightFile(uri) || seen[uri] {
			return
		}
		seen[uri] = true
		files = append(files, vram.FileInput{URI: resolveEstimateURI(uri, ml.ModelPath), Size: knownSize})
	}

	add(modelFile, 0)
	if opts.gRPCOptions != nil {
		// A projector or companion file shows up as an option value. It is part
		// of the load and is charged to extras, not the weights.
		for _, opt := range opts.gRPCOptions.Options {
			_, value, ok := strings.Cut(opt, ":")
			if ok && value != "" && vram.IsWeightFile(value) {
				add(value, 0)
			}
		}
	}

	estimate := LoadEstimate{}
	if len(files) == 0 {
		estimate.Weights = residency.Component{Provenance: residency.Unknown}
		estimate.Context = residency.Component{Provenance: residency.Unknown}
		estimate.Extras = residency.Component{Provenance: residency.Unknown}
		return estimate
	}

	subCtx := ctx
	if subCtx == nil {
		subCtx = context.Background()
	}
	var cancel context.CancelFunc
	if _, ok := subCtx.Deadline(); !ok {
		subCtx, cancel = context.WithTimeout(subCtx, estimateTimeout)
		defer cancel()
	}

	ctxLen := uint32(0)
	if opts.gRPCOptions != nil && opts.gRPCOptions.ContextSize > 0 {
		ctxLen = uint32(opts.gRPCOptions.ContextSize)
	}
	if ctxLen == 0 {
		ctxLen = 8192
	}

	// Weight bytes alone, without a header: the figure the account charges as
	// weights even when the KV term cannot be computed.
	var weightBytes uint64
	for _, f := range files {
		if f.Size > 0 {
			weightBytes += uint64(f.Size)
			continue
		}
		if n, err := vram.DefaultCachedSizeResolver().ContentLength(subCtx, f.URI); err == nil && n > 0 {
			weightBytes += uint64(n)
		}
	}

	multi, err := vram.EstimateMultiContext(subCtx, files, []uint32{ctxLen},
		vram.EstimateOptions{}, vram.DefaultCachedSizeResolver(), vram.DefaultCachedGGUFReader())
	if err != nil || multi.SizeBytes == 0 {
		// The size of the weights could still be known even when the
		// architecture could not be read; report what we have and keep the KV
		// term unknown rather than zero.
		estimate.Weights = residency.Component{Provenance: residency.Unknown}
		if weightBytes > 0 {
			estimate.Weights = residency.Component{Bytes: weightBytes, Provenance: residency.Estimated}
			estimate.WeightBytes = int64(weightBytes)
		}
		estimate.Context = residency.Component{Provenance: residency.Unknown}
		estimate.Extras = residency.Component{Bytes: 0, Provenance: residency.Estimated}
		return estimate
	}

	weights := multi.SizeBytes
	if weights == 0 {
		weights = weightBytes
	}

	// The estimator's figure is weights plus the KV/compute term. Split it so
	// the ledger can label the cache part honestly: the KV term is the total
	// minus the weights it was computed from. Without a header the estimator
	// still returns a size-only figure with a rule-of-thumb KV term, so the
	// context part is reported as estimated rather than measured.
	total := multi.VRAMForContext(ctxLen)
	if total == 0 {
		total = multi.SizeBytes
	}
	var contextBytes uint64
	if total > weights {
		contextBytes = total - weights
	}
	estimate.Weights = residency.Component{Bytes: weights, Provenance: residency.Estimated}
	estimate.Context = residency.Component{Bytes: contextBytes, Provenance: residency.Estimated}
	estimate.Extras = residency.Component{Bytes: 0, Provenance: residency.Estimated}
	estimate.WeightBytes = int64(weights)
	return estimate
}

// EstimateForAdmission is the BackendEstimateFunc the loader hands the
// residency ledger. The backend argument is accepted for a future
// per-engine estimate; the figure is currently the same for every engine in
// one model configuration, which is enough to decide admission.
func (ml *ModelLoader) EstimateForAdmission(ctx context.Context, backend string, modelFile string, opts *Options) LoadEstimate {
	return ml.estimateForBackend(ctx, modelFile, opts)
}

const estimateTimeout = 10 * time.Second

// resolveEstimateURI turns a relative model path into a file:// URI so the
// size resolver can stat it, leaving a URI with a scheme untouched.
func resolveEstimateURI(uri, modelsPath string) string {
	if strings.Contains(uri, "://") {
		return uri
