func (ml *ModelLoader) forgetExitedProcess(id string, p *process.Process) {
	release := ml.operations.acquire(id, true)
	defer release()
	ml.mu.Lock()
	store := ml.store
	hooks := append([]ModelUnloadHook(nil), ml.onUnloadHooks...)
	ml.mu.Unlock()
