// ConfigureResidency resolves the operator's memory budgets and installs the
// ledger on the model loader. It runs at startup and again whenever a budget
// changes.
//
// Admission is installed whenever it is switched on, even with no cap: the
// observation surface then shows what is loaded and loading, and nothing is
// ever refused because an uncapped pool admits every load. With admission off
// the ledger is not installed at all and behaviour is exactly as before.
func (a *Application) ConfigureResidency() {
	appConfig := a.ApplicationConfig()
	if appConfig == nil || a.modelLoader == nil {
		return
	}
	if !appConfig.ResidencyAdmission {
		a.modelLoader.SetResidency(nil)
		xlog.Debug("Residency admission is off")
		return
	}

	deviceLimit := residency.ResolveLimit(detectedDeviceCapacity(), appConfig.VRAMBudget)
	hostLimit := residency.ResolveLimit(detectedHostCapacity(), appConfig.MemoryBudget)

	order := residency.ReclaimLeastRecentlyUsed
	if appConfig.ResidencyReclaimOrder == "largest" {
		order = residency.ReclaimLargestFirst
	}

	a.modelLoader.ConfigureResidency(model.ResidencyOptions{
		DeviceLimit:   deviceLimit,
		HostLimit:     hostLimit,
