		"order", order)
}

const (
	capacityReclaimMax    = 8
	capacityReclaimBudget = 30 * time.Second
)

// detectedDeviceCapacity is the physical device memory the VRAM budget is
// resolved against. It reads the budgeted total, so an existing
// LOCALAI_VRAM_BUDGET and the new pool cap compose rather than double-count.
func detectedDeviceCapacity() uint64 {
	if total, err := xsysinfo.TotalAvailableVRAM(); err == nil && total > 0 {
		return total
	}
	// A unified-memory host with no separate VRAM figure reports its RAM as
	// device memory through the detector; if it still reports none, the device
	// pool is simply unknown and stays uncapped.
	return 0
}

// detectedHostCapacity is the total system memory the host budget resolves
// against, container-aware.
func detectedHostCapacity() uint64 {
	info, err := xsysinfo.GetSystemRAMInfo()
	if err != nil || info == nil {
		return 0
	}
	return info.Total
}

// CurrentResidencyLimits resolves the limits from the live configuration
// without installing them. It is used by the observation endpoint so a client
// can size a model against the same figures admission would use.
func CurrentResidencyLimits(appConfig *config.ApplicationConfig) (device, host residency.Limit) {
	if appConfig == nil {
		return residency.Limit{}, residency.Limit{}
	}
	return residency.ResolveLimit(detectedDeviceCapacity(), appConfig.VRAMBudget),
		residency.ResolveLimit(detectedHostCapacity(), appConfig.MemoryBudget)
}
