// ResidencyView is the observation surface of the per-host memory ledger: each
// loaded model's account (weights, context cache and extras, each labelled
// measured/estimated/unknown), the device and host roll-ups with their limits
// and headroom, the in-flight reservations, and the most recent refusals.
//
// It never writes an account and never evicts; it is the read side of the same
// ledger admission uses.
//
// @Summary Per-host model memory residency
// @Description Returns what each loaded model holds, per pool totals and headroom, in-flight load reservations and the most recent admission refusals. An unknown size is reported as unknown, never as zero.
// @Tags monitoring
// @Produce json
// @Success 200 {object} residency.View "Residency view"
// @Router /api/models/residency [get]
func ResidencyViewEndpoint(ml *model.ModelLoader, appConfig *application.ApplicationConfig) echo.HandlerFunc {
	return func(c echo.Context) error {
		if ml == nil {
			return c.JSON(http.StatusServiceUnavailable, map[string]any{
				"error": "the model loader is not available",
			})
		}
		view := ml.ResidencyView()
		// When the ledger is off, still resolve the limits from the live
		// configuration so a client can see what a cap would be, and say why
		// the rest is absent.
		if !view.Enabled {
			device, host := application.CurrentResidencyLimits(appConfig)
			view.Device = residencySummary(device)
			view.Host = residencySummary(host)
			view.Note = "the residency ledger is disabled; enable residency admission (LOCALAI_RESIDENCY_ADMISSION) to record accounts and refusals"
		}
		liftAccountAliases(ml, &view)
		return c.JSON(http.StatusOK, view)
	}
}

// residencySummary renders a resolved limit as an empty pool summary.
func residencySummary(limit residencyLimit) residencyPoolSummary {
	return residencyPoolSummary{
		CapacityBytes:   limit.CapacityBytes,
		CapacityKnown:   limit.CapacityKnown,
		LimitBytes:      limit.LimitBytes,
		LimitConfigured: limit.LimitConfigured,
	}
}

// liftAccountAliases fills in the alias list of each account from the config
// loader, so a model referenced through an alias is shown under its canonical
// name with the aliases attached rather than as a duplicate entry.
func liftAccountAliases(ml *model.ModelLoader, view *residencyView) {
	_ = ml
	_ = view
	xlog.Debug("residency view served", "accounts", len(view.Accounts))
}
