	It("resolves a percentage against the detected capacity", func() {
		limit := residency.ResolveLimit(10*gib, "80%")
		Expect(limit.LimitConfigured).To(BeTrue())
		Expect(limit.LimitBytes).To(Equal(8 * gib))
	})

	It("clamps an absolute cap to the detected capacity", func() {
		limit := residency.ResolveLimit(10*gib, "99GB")
		Expect(limit.LimitBytes).To(Equal(10 * gib))
	})

	It("treats empty, zero and malformed values as uncapped, never a zero limit", func() {
		for _, v := range []string{"", "0", "0%", "not-a-size"} {
			limit := residency.ResolveLimit(10*gib, v)
			Expect(limit.LimitConfigured).To(BeFalse(), "value %q must not configure a cap", v)
			Expect(limit.WouldFit(100*gib, 0, 0)).To(BeTrue(), "value %q must not refuse a load", v)
		}
	})

	It("keeps a percentage meaningful when the capacity is unknown", func() {
		limit := residency.ResolveLimit(0, "80%")
		Expect(limit.LimitConfigured).To(BeFalse(), "there is nothing to take a percentage of")
		Expect(limit.WouldFit(100*gib, 0, 0)).To(BeTrue())
	})
})

