func TestResidency(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Residency test suite")
}

const gib = uint64(1024 * 1024 * 1024)

func measured(n uint64) residency.Component {
	return residency.Component{Bytes: n, Provenance: residency.Measured}
}

func estimated(n uint64) residency.Component {
	return residency.Component{Bytes: n, Provenance: residency.Estimated}
}

func unknown() residency.Component {
	return residency.Component{Provenance: residency.Unknown}
}

// account builds a resident host-memory account with one measured size.
func account(model string, bytes uint64) residency.Account {
	return residency.Account{
		Model:    model,
		Pool:     residency.PoolHost,
		Weights:  measured(bytes),
		Context:  estimated(0),
		Extras:   estimated(0),
		LastUsed: time.Now(),
	}
}

// deviceLimit returns a configured device-only Config for a 10 GiB pool.
func deviceLimit() residency.Config {
	return residency.Config{
		Device: residency.Limit{CapacityBytes: 10 * gib, CapacityKnown: true, LimitBytes: 10 * gib, LimitConfigured: true},
	}
}

var _ = Describe("Provenance and bytes", func() {
	It("never renders an unknown size as a zero", func() {
		u := unknown()
		Expect(u.Known()).To(BeFalse())
		Expect(u.Display()).To(Equal("unknown"))
		Expect(u.Normalized().Bytes).To(BeZero(), "the byte count of an unknown is zero, but its provenance says unknown")
	})

	It("runs through the least trustworthy provenance when combining components", func() {
		total := residency.Account{
			Weights: measured(100),
			Context: estimated(50),
			Extras:  measured(10),
		}.EstimatedTotal()
		Expect(total.Bytes).To(Equal(uint64(160)))
		Expect(total.Provenance).To(Equal(residency.Estimated))
	})

	It("makes a total unknown when the weights are unknown", func() {
		total := residency.Account{
			Weights: unknown(),
			Context: estimated(50),
		}.EstimatedTotal()
		Expect(total.Known()).To(BeFalse())
	})
})

var _ = Describe("Limit resolution", func() {
	It("resolves a percentage against the detected capacity", func() {
		limit := residency.ResolveLimit(10*gib, "80%")
		Expect(limit.LimitConfigured).To(BeTrue())
		Expect(limit.LimitBytes).To(Equal(8 * gib))
	})

	It("clamps an absolute cap to the detected capacity", func() {
		limit := residency.ResolveLimit(10*gib, "99GB")
		Expect(limit.LimitBytes).To(Equal(10 * gib))
	})

	It("treats empty, zero and malformed values as uncapped, never a zero limit", func() {
		for _, v := range []string{"", "0", "0%", "not-a-size"} {
			limit := residency.ResolveLimit(10*gib, v)
			Expect(limit.LimitConfigured).To(BeFalse(), "value %q must not configure a cap", v)
			Expect(limit.WouldFit(100*gib, 0, 0)).To(BeTrue(), "value %q must not refuse a load", v)
		}
	})

	It("keeps a percentage meaningful when the capacity is unknown", func() {
		limit := residency.ResolveLimit(0, "80%")
		Expect(limit.LimitConfigured).To(BeFalse(), "there is nothing to take a percentage of")
		Expect(limit.WouldFit(100*gib, 0, 0)).To(BeTrue())
	})
})

var _ = Describe("Ledger admission", func() {
	It("admits and reserves when the load fits", func() {
		l := residency.NewLedger(deviceLimit())
		d := l.Admit(context.Background(), residency.Need{Account: account("a", 4*gib)}, nil)
		Expect(d.Admitted).To(BeTrue())
		Expect(d.Reservation).NotTo(BeNil())
		view := l.Snapshot()
		Expect(view.Device.ReservedBytes).To(Equal(4 * gib))
		Expect(view.Device.HeadroomBytes).To(Equal(6 * gib))
	})

	It("reclaims in LRU order and admits after freeing room", func() {
		l := residency.NewLedger(deviceLimit())
		l.Settle(account("old", 5*gib))
		l.Settle(account("new", 4*gib))

		var evicted []string
		d := l.Admit(context.Background(), residency.Need{Account: account("third", 4*gib)},
			func(a residency.Account) error { evicted = append(evicted, a.Model); return nil })
		Expect(d.Admitted).To(BeTrue())
		Expect(evicted).To(ConsistOf("old"), "LRU frees the least recently used model first")
		_, stillThere := l.Resident("new")
		Expect(stillThere).To(BeTrue())
	})

	It("reclaims largest-first when configured", func() {
		cfg := deviceLimit()
		cfg.ReclaimOrder = residency.ReclaimLargestFirst
		l := residency.NewLedger(cfg)
		l.Settle(account("small", 2*gib))
		l.Settle(account("large", 5*gib))

		var evicted []string
		d := l.Admit(context.Background(), residency.Need{Account: account("third", 4*gib)},
			func(a residency.Account) error { evicted = append(evicted, a.Model); return nil })
		Expect(d.Admitted).To(BeTrue())
		Expect(evicted).To(ConsistOf("large"))
	})

	It("refuses with the byte shortfall when nothing can be reclaimed", func() {
		l := residency.NewLedger(deviceLimit())
		l.Settle(residency.Account{
			Model: "pinned", Pool: residency.PoolHost, Pinned: true,
			Weights: measured(9 * gib), Context: estimated(0), Extras: estimated(0),
		})

		d := l.Admit(context.Background(), residency.Need{Account: account("incoming", 4*gib)}, nil)
		Expect(d.Admitted).To(BeFalse())
		Expect(d.Rejection).NotTo(BeNil())
		Expect(d.Rejection.Reason).To(Equal(residency.ReasonNoReclaimable))
		Expect(d.Rejection.Shortfall).To(Equal(3 * gib), "9 resident + 4 requested - 10 limit")
		Expect(d.Rejection.Held).To(ConsistOf("pinned"))
		Expect(d.Rejection.Message()).To(ContainSubstring("pinned"), "the reason names what is holding the room")
	})

	It("admits a load whose size is unknown instead of refusing it", func() {
		l := residency.NewLedger(deviceLimit())
		inc := residency.Account{Model: "m", Pool: residency.PoolHost, Weights: unknown()}
		d := l.Admit(context.Background(), residency.Need{Account: inc}, nil)
		Expect(d.Admitted).To(BeTrue(), "an estimate gap must not fail a load that could succeed")
		Expect(d.Uncertain).To(BeTrue())
	})

	It("admits when a resident size is unknown rather than guessing a refusal", func() {
		l := residency.NewLedger(deviceLimit())
		l.Settle(residency.Account{Model: "unmeasured", Pool: residency.PoolHost, Weights: unknown()})
		d := l.Admit(context.Background(), residency.Need{Account: account("incoming", 4*gib)}, nil)
		Expect(d.Admitted).To(BeTrue())
		Expect(d.Uncertain).To(BeTrue())
	})

	It("never refuses when the pool is uncapped", func() {
		l := residency.NewLedger(residency.Config{})
		d := l.Admit(context.Background(), residency.Need{Account: account("huge", 1000*gib)}, nil)
		Expect(d.Admitted).To(BeTrue())
		Expect(d.Rejection).To(BeNil())
	})

	It("records a refusal in the view's recent list", func() {
		l := residency.NewLedger(deviceLimit())
		l.Settle(residency.Account{Model: "held", Pool: residency.PoolHost, Pinned: true,
			Weights: measured(9 * gib)})
		d := l.Admit(context.Background(), residency.Need{Account: account("incoming", 4*gib)}, nil)
		Expect(d.Admitted).To(BeFalse())
		view := l.Snapshot()
		Expect(view.Rejections).To(HaveLen(1))
		Expect(view.Rejections[0].Model).To(Equal("incoming"))
		Expect(view.Rejections[0].Provenance).To(Equal(residency.Measured))
	})
})

