var _ = Describe("Concurrent admission", func() {
	It("admits one of two loads that each fit but not together", func() {
		l := residency.NewLedger(deviceLimit())

		var admitted int32
		var wg sync.WaitGroup
		start := make(chan struct{})
		for _, name := range []string{"a", "b"} {
			wg.Add(1)
			go func(model string) {
				defer wg.Done()
				<-start
				d := l.Admit(context.Background(), residency.Need{Account: account(model, 6*gib)},
					// No eviction is possible (nothing is settled), so the
					// loser must be refused rather than take the same bytes.
					nil)
				if d.Admitted && d.Reservation != nil {
					atomic.AddInt32(&admitted, 1)
					// Hold the reservation so the peer cannot reuse the headroom.
					time.Sleep(20 * time.Millisecond)
					d.Reservation.Release()
				}
			}(name)
		}
		close(start)
		wg.Wait()

		Expect(admitted).To(Equal(int32(1)), "exactly one of two 6-GiB loads fits a 10-GiB pool")
		view := l.Snapshot()
		Expect(view.Device.ReservedBytes).To(BeZero(), "both reservations returned")
	})

	It("does not double-evict a model when admission and periodic reclaim race", func() {
		l := residency.NewLedger(deviceLimit())
		l.Settle(account("shared", 9*gib))

		var evictions int32
		var wg sync.WaitGroup
		wg.Add(2)
		start := make(chan struct{})
		evict := func(a residency.Account) error {
			atomic.AddInt32(&evictions, 1)
			return nil
		}
		go func() {
			defer wg.Done()
			<-start
			l.Admit(context.Background(), residency.Need{Account: account("incoming", 6*gib)}, evict)
		}()
		go func() {
			defer wg.Done()
			<-start
			l.Reclaim(context.Background(), residency.PoolDevice, evict, 6*gib)
		}()
		close(start)
		wg.Wait()

		Expect(evictions).To(Equal(int32(1)), "a model may be evicted only once")
	})
})

