// attachResidency adds each resident model's ledger entry to its system row.
func attachResidency(models []schema.SysInfoModel, view residency.View) {
	byName := make(map[string]residency.Account, len(view.Accounts))
	for _, a := range view.Accounts {
		byName[a.Model] = a
	}
	for i := range models {
		a, ok := byName[models[i].ID]
