			Known:   charge.Known(),
			Weights: sysInfoComponent(a.Weights),
			Context: sysInfoComponent(a.Context),
			Extras:  sysInfoComponent(a.Extras),
			Pinned:  a.Pinned,
		}
		models[i].Residency = entry
	}
}

func sysInfoComponent(c residency.Component) schema.SysInfoComponent {
	c = c.Normalized()
	return schema.SysInfoComponent{Bytes: c.Bytes, Provenance: string(c.Provenance)}
