func (c *Client) ModelResidency(_ context.Context) (*localaitools.ResidencyView, error) {
	if c.ModelLoader == nil {
		return &localaitools.ResidencyView{Enabled: false, Note: "no model loader is wired"}, nil
	}
	view := c.ModelLoader.ResidencyView()
	return residencyViewToDTO(view), nil
}

func residencyComponentToDTO(c residency.Component) localaitools.ResidencyComponent {
	c = c.Normalized()
	return localaitools.ResidencyComponent{Bytes: c.Bytes, Provenance: string(c.Provenance)}
}

func residencyViewToDTO(view residency.View) *localaitools.ResidencyView {
	out := &localaitools.ResidencyView{
		Enabled: view.Enabled,
		Note:    view.Note,
		Device:  residencyPoolToDTO(view.Device),
		Host:    residencyPoolToDTO(view.Host),
	}
	for _, a := range view.Accounts {
		acct := localaitools.ResidencyAccount{
			Model:   a.Model,
			Backend: a.Backend,
			Pool:    string(a.Pool),
			Pinned:  a.Pinned,
			Weights: residencyComponentToDTO(a.Weights),
			Context: residencyComponentToDTO(a.Context),
			Extras:  residencyComponentToDTO(a.Extras),
		}
		if a.Measured != nil {
			m := residencyComponentToDTO(*a.Measured)
			acct.Measured = &m
		}
		out.Accounts = append(out.Accounts, acct)
	}
	for _, r := range view.Reservations {
		out.Reservations = append(out.Reservations, localaitools.ResidencyReservation{
			Model: r.Model, Backend: r.Backend, Pool: string(r.Pool),
			Bytes: r.Bytes, Provenance: string(r.Provenance),
		})
	}
	for _, r := range view.Rejections {
		out.Rejections = append(out.Rejections, localaitools.ResidencyRejection{
			Model: r.Model, Backend: r.Backend, Pool: string(r.Pool),
			NeededBytes: r.NeededBytes, Provenance: string(r.Provenance),
			Resident: r.Resident, Reserved: r.Reserved, Limit: r.Limit,
			Shortfall: r.Shortfall, Reclaimable: r.Reclaimable, Held: r.Held, Reason: r.Reason,
		})
	}
	return out
}

