		if ledger := ml.ResidencyLedger(); ledger != nil {
			ledger.Close()
		}
	})

	It("skips a candidate engine that does not fit without starting it, and explains why", func() {
		ledger := residency.NewLedger(residency.Config{
			Device: residency.Limit{CapacityBytes: 10 * resGib, CapacityKnown: true,
				LimitBytes: 10 * resGib, LimitConfigured: true},
		})
		ml.SetResidency(ledger)
		// A pinned 9 GiB resident leaves room for a 4 GiB load to be refused.
		ledger.Settle(residency.Account{Model: "resident", Pool: residency.PoolHost, Pinned: true,
			Weights: residency.Component{Bytes: 9 * resGib, Provenance: residency.Measured},
			Context: residency.Component{Bytes: 0, Provenance: residency.Estimated},
			Extras:  residency.Component{Bytes: 0, Provenance: residency.Estimated}})

		started := map[string]int{}
		var mu sync.Mutex
		estimate := func(backend string) LoadEstimate {
			mu.Lock()
			started[backend]++
			mu.Unlock()
			return fixedEstimator(4 * resGib)(backend)
		}

		_, _, err := ml.AdmitCandidates(context.Background(), "incoming",
			[]string{"engine-a", "engine-b"}, nil, estimate)
		Expect(err).To(HaveOccurred())
		var all *residency.AllCandidatesRejectedError
		Expect(err).To(BeAssignableToTypeOf(all))
		Expect(err.(*residency.AllCandidatesRejectedError).Candidates).To(HaveLen(2))
		Expect(err.Error()).To(ContainSubstring("engine-a"))
		Expect(err.Error()).To(ContainSubstring("engine-b"))
	})

	It("admits the first candidate that fits and stops there", func() {
		ledger := residency.NewLedger(residency.Config{
			Device: residency.Limit{CapacityBytes: 10 * resGib, CapacityKnown: true,
				LimitBytes: 10 * resGib, LimitConfigured: true},
		})
		ml.SetResidency(ledger)

		var estimated []string
		var mu sync.Mutex
		choice, res, err := ml.AdmitCandidates(context.Background(), "incoming",
			[]string{"engine-a", "engine-b"}, nil, func(backend string) LoadEstimate {
				mu.Lock()
				estimated = append(estimated, backend)
				mu.Unlock()
				return fixedEstimator(4 * resGib)(backend)
			})
		Expect(err).NotTo(HaveOccurred())
		Expect(choice).To(Equal("engine-a"))
		Expect(res).NotTo(BeNil())
		Expect(estimated).To(ConsistOf("engine-a"), "the second candidate is never estimated once the first is admitted")
		res.Release()
	})

	It("admits everything when the pool is uncapped, even a load far over any capacity", func() {
		ledger := residency.NewLedger(residency.Config{}) // no limits
		ml.SetResidency(ledger)
		choice, res, err := ml.AdmitCandidates(context.Background(), "incoming",
			[]string{"engine-a"}, nil, fixedEstimator(1000*resGib))
		Expect(err).NotTo(HaveOccurred())
		Expect(choice).To(Equal("engine-a"))
		res.Release()
	})

	It("releases a reservation when the load fails, so the next attempt sees the room", func() {
		ledger := residency.NewLedger(residency.Config{
			Device: residency.Limit{CapacityBytes: 10 * resGib, CapacityKnown: true,
				LimitBytes: 10 * resGib, LimitConfigured: true},
		})
		ml.SetResidency(ledger)

		// A reservation that never settles must return its bytes.
		view := ledger.Admit(context.Background(), residency.Need{Account: residency.Account{
			Model: "attempt", Pool: residency.PoolHost,
			Weights: residency.Component{Bytes: 6 * resGib, Provenance: residency.Measured},
			Context: residency.Component{Bytes: 0, Provenance: residency.Estimated},
			Extras:  residency.Component{Bytes: 0, Provenance: residency.Estimated},
		}}, nil)
		Expect(view.Admitted).To(BeTrue())
		Expect(ledger.Snapshot().Host.ReservedBytes).To(Equal(6 * resGib))
		view.Reservation.Release()
		Expect(ledger.Snapshot().Host.ReservedBytes).To(BeZero())
	})

	It("keeps one account for a model referenced twice (alias)", func() {
		ledger := residency.NewLedger(residency.Config{})
		ml.SetResidency(ledger)
		ml.settleResidency("canonical", "alias", "engine", "", nil,
			fixedEstimator(3*resGib)("engine"), 0)
		ml.settleResidency("canonical", "canonical", "engine", "", nil,
			fixedEstimator(3*resGib)("engine"), 0)
		view := ml.ResidencyView()
		Expect(view.Accounts).To(HaveLen(1))
		Expect(view.Accounts[0].Aliases).To(ContainElement("alias"))
	})

	It("drops the account on unload so the room is visible again", func() {
		ledger := residency.NewLedger(residency.Config{})
		ml.SetResidency(ledger)
		ml.settleResidency("m", "m", "engine", "", nil, fixedEstimator(5*resGib)("engine"), 0)
		Expect(ml.ResidencyView().Accounts).To(HaveLen(1))
		ml.releaseResidency("m")
		Expect(ml.ResidencyView().Accounts).To(BeEmpty())
	})

	It("reports a disabled view, with the resolved limits, when no ledger is installed", func() {
		view := ml.ResidencyView()
		Expect(view.Enabled).To(BeFalse())
		Expect(view.Note).NotTo(BeEmpty())
	})
})

