193	func (ml *ModelLoader) settleResidency(modelID, modelName, backend, address string, opts *Options, estimate LoadEstimate, pid int) {
194		ledger := ml.residencyLedger()
195		if ledger == nil {
196			return
197		}
198		account := residency.Account{
199			Model:   modelID,
200			Backend: backend,
201			Address: address,
202			Pool:    ml.poolForBackend(backend, address, opts),
203			Weights: estimate.Weights,
204			Context: estimate.Context,
205			Extras:  estimate.Extras,
206		}
207		if ml.isRemoteAttachment(address) {
208			// A model attached to an external address runs on another host. The
209			// local ledger must not charge it, or a fleet of remote placements
210			// would look like local pressure. Record it with no charge so the view
211			// still lists it.
212			account.Measured = &residency.Component{Provenance: residency.Unknown}
213			ledger.Settle(account)
214			return
215		}
216		if measured, ok := estimateMeasured(pid, account.Pool, account.EstimatedTotal()); ok {
217			account.Measured = &measured
218		}
219		if modelName != "" && modelName != modelID {
220			account.Aliases = []string{modelName}
221		}
222		ledger.Settle(account)
223	}
