// reservation committed and the account written together, so an alias or a
// repeated load updates the same entry.
func (ml *ModelLoader) settleResidency(modelID, modelName, backend, address string, opts *Options, estimate LoadEstimate, pid int) {
	ledger := ml.residencyLedger()
	if ledger == nil {
		return
	}
	account := residency.Account{
		Model:   modelID,
		Backend: backend,
		Address: address,
		Pool:    ml.poolForBackend(backend, address, opts),
		Weights: estimate.Weights,
		Context: estimate.Context,
		Extras:  estimate.Extras,
	}
	if ml.isRemoteAttachment(address) {
		// A model attached to an external address runs on another host. The
		// local ledger must not charge it, or a fleet of remote placements
		// would look like local pressure. Record it with no charge so the view
		// still lists it.
		account.Measured = &residency.Component{Provenance: residency.Unknown}
		ledger.Settle(account)
		return
	}
	if measured, ok := estimateMeasured(pid, account.Pool, account.EstimatedTotal()); ok {
		account.Measured = &measured
	}
	if modelName != "" && modelName != modelID {
		account.Aliases = []string{modelName}
	}
	ledger.Settle(account)
}

// releaseResidency drops the account of an unloaded model. It is called for a
// graceful unload, an eviction, a crashed process and a lost backend.
func (ml *ModelLoader) releaseResidency(modelID string) {
	if ledger := ml.residencyLedger(); ledger != nil {
		ledger.Remove(modelID)
	}
}

// releaseResidencyByAddress drops the account holding a backend address; it is
// the release path for a lost remote backend whose name may not be known.
func (ml *ModelLoader) releaseResidencyByAddress(address string) {
	if ledger := ml.residencyLedger(); ledger != nil {
		ledger.RemoveByAddress(address)
	}
}

// touchResidency updates the last-used time of a resident model for the LRU
// reclaim order.
func (ml *ModelLoader) touchResidency(modelID string) {
	if ledger := ml.residencyLedger(); ledger != nil {
		ledger.Touch(modelID, time.Time{})
	}
}

